using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using Unity.Profiling;
namespace SporeGobbo.Geometry.Preview
{
 [DefaultExecutionOrder(1500)]public sealed class Stage55Benchmark:MonoBehaviour
 {
  Stage55Preview env;Stage47Preview live;Stage49Preview cam;string output;bool finished;ProfilerRecorder allocation,main;readonly Results result=new Results();
  [Serializable]public class Results{public string error="",colorSpace;public double explorationSeconds;public int initialKnown,finalKnown,laps;public List<string> checks=new List<string>();public List<Frame> frames=new List<Frame>();public List<Metric> metrics=new List<Metric>();public List<Resource> resources=new List<Resource>();public List<Shot> shots=new List<Shot>();public List<long> probes=new List<long>();}
  [Serializable]public class Frame{public string phase;public double interval,host,discovery,publication,structure,emergence,main,elevated,encounter;public long allocation;public double build,unload,upload,gpu;public int resident,known,shown,uploads,built,evicted;public bool ready;}
  [Serializable]public class Metric{public string name;public double ms;public int count;}
  [Serializable]public class Resource{public string name;public long managed,unity;public int meshes,buffers,materials,resident,pool;}
  [Serializable]public class Shot{public string name;public double above,below,normalScale;public int anchor,known,shown,resident,visible;public float x,y;}
  IEnumerator Start(){var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-stage55Output");if(at<0)yield break;output=args[at+1];Directory.CreateDirectory(output);env=GetComponent<Stage55Preview>();env.Initialize();env.automation=true;live=env.Live;live.automation=true;cam=env.CameraStudy;env.showPanel=false;env.Lab.paused=true;QualitySettings.vSyncCount=0;Application.runInBackground=true;bool controlsOnly=Array.IndexOf(args,"-stage55ControlsOnly")>=0;Application.targetFrameRate=controlsOnly?-1:60;allocation=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");main=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread");result.colorSpace=QualitySettings.activeColorSpace.ToString();result.initialKnown=env.State.Discovery.Remembered.Count;yield return Settle();RecordMetric("initialization",env.InitializationMs);RecordMetric("organic-assembly",env.AssemblyMs);ResourceSample("initial");for(int p=0;p<4;p++){var b=new byte[1048576];b[0]=1;yield return null;result.probes.Add(allocation.Valid?allocation.LastValue:-1);GC.KeepAlive(b);}yield return Capture("01-start-only-chamber-known");
   // Real five minutes at60FPS; logical motion uses measured dt and the existing swept movement. No bookmarks during the circuit.
   double start=Time.realtimeSinceStartupAsDouble,previous=start;int waypoint=1;var path=new List<Point2>();int cursor=0;bool routeReady=false;double nextSample=60;while(controlsOnly?result.laps<1:Time.realtimeSinceStartupAsDouble-start<300){double now=Time.realtimeSinceStartupAsDouble,dt=controlsOnly?1.0/60:Math.Min(.05,now-previous);previous=now;if(!routeReady){var nav=new LabNavigation(live.World,new Point2(live.Position.x,live.Position.y));path.Clear();Check(nav.TraceToRoot(env.State.Fixture.Tour[waypoint],1,path),"Circuit route "+waypoint+" lap "+result.laps);path.Reverse();cursor=0;routeReady=true;}
    if(live.Ready){while(cursor<path.Count&&Vector2.Distance(live.Position,Stage55Preview.V(path[cursor]))<.00001f)cursor++;if(cursor>=path.Count){waypoint++;if(waypoint>=env.State.Fixture.Tour.Count){waypoint=0;result.laps++;}routeReady=false;}else{var delta=Stage55Preview.V(path[cursor])-live.Position;live.Step(Vector2.ClampMagnitude(delta/(float)(10*Math.Max(.001,dt)),1),delta,false,(float)dt);}}env.Process(dt);yield return null;Record(controlsOnly?"physical-circuit-replay":"five-minute-exploration",(Time.realtimeSinceStartupAsDouble-now)*1000);if(Time.realtimeSinceStartupAsDouble-start>=nextSample){ResourceSample("exploration-"+(int)nextSample);yield return Capture("02-circuit-"+(int)nextSample);nextSample+=60;previous=Time.realtimeSinceStartupAsDouble;}}
   result.explorationSeconds=Time.realtimeSinceStartupAsDouble-start;File.WriteAllText(Path.Combine(output,"five-minute-checkpoint.json"),JsonUtility.ToJson(result,true));result.finalKnown=env.State.Discovery.Remembered.Count;Application.targetFrameRate=-1;Check(result.finalKnown>result.initialKnown+500,"Exploration learns geography without world pre-reveal");Check(result.laps>=1,"Completed integrated connected circuit");
   for(int profile=0;profile<4;profile++){env.silhouette=profile;env.ResetDemo();env.Go(1);yield return Settle();yield return Capture("03-profile-"+profile+"-north");foreach(var offset in new[]{new DualTile(18,-43),new DualTile(18,-11),new DualTile(2,-27),new DualTile(34,-27)}){var destination=Stage55Preview.V(env.State.Fixture.P(offset.X,offset.Y));live.Teleport(destination);Check(Vector2.Distance(live.Position,destination)<.01f,"Verified angle "+offset.X+","+offset.Y);env.Process(.2);yield return Settle();yield return Capture("04-profile-"+profile+"-angle-"+offset.X+"-"+offset.Y);}}
   env.silhouette=1;env.RebuildElevated();env.Go(1);yield return Settle();for(int mode=0;mode<2;mode++){env.legacyProjection=mode==0;yield return Capture("05-height-contract-"+mode);int builds=env.ElevatedBuilds;for(int i=0;i<120;i++){live.SetPreviewFocus(live.Position+new Vector2(Mathf.Sin(i*.05f)*8,Mathf.Cos(i*.05f)*12));yield return null;Record("controlled-camera-"+mode,Time.unscaledDeltaTime*1000);if(i==0||i==60||i==119)yield return Capture("05a-controlled-"+mode+"-"+i);}Check(env.ElevatedBuilds==builds,"Camera-only motion retains structure topology "+mode);}env.legacyProjection=false;
   env.Go(1);live.Teleport(Stage55Preview.V(env.State.Fixture.P(18,-39)));env.Process(.2);yield return Settle();yield return Capture("05b-spike-before-excavation");Check(!live.World.Excavate(env.State.Fixture.X+18,env.State.Fixture.Y-27),"Protected spike remains authoritative");foreach(var point in new[]{new DualTile(18,-34),new DualTile(9,-32),new DualTile(8,-27),new DualTile(10,-21),new DualTile(18,-20),new DualTile(26,-22),new DualTile(28,-27),new DualTile(26,-32)})yield return ExcavateTo(env.State.Fixture.P(point.X,point.Y),"spike-collar");yield return Capture("05c-spike-collar-exposed");
   env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(-15,10)));yield return Settle();yield return ExcavateTo(env.State.Fixture.P(-31,4),"small-pocket");yield return Frames("small-reveal",30);yield return Capture("06-small-pocket");
   for(int style=0;style<3;style++){env.reveal=style;env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(-28,-28)));yield return Settle();env.Lab.paused=false;yield return ExcavateTo(env.State.Fixture.P(-45,-26),"occupied-"+style);yield return Frames("occupied-"+style,150);yield return Capture("07-occupied-"+style);for(int i=0;i<3;i++)Check(env.Lab.Actors[i].SpawnValid,"Pre-existing occupied threat "+i+" style "+style);env.Lab.paused=true;}
   for(int style=0;style<3;style++){env.reveal=style;env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(-60,-4)));yield return Settle();yield return ExcavateTo(env.State.Fixture.P(-77,12),"large-chamber-"+style);yield return Frames("large-reveal-"+style,60);yield return Capture("08-large-chamber-"+style);}
   env.reveal=2;env.ResetDemo();live.Teleport(Stage55Preview.V(env.State.Fixture.P(76,-1)));yield return Settle();yield return ExcavateTo(env.State.Fixture.P(94,-25),"network");yield return Frames("bounded-network",60);yield return Capture("09-bounded-network");Check(!env.State.Discovery.Known(env.State.Fixture.X+149,env.State.Fixture.Y-8),"Far network stays concealed");
   env.Go(2);yield return Settle();yield return Capture("10-root-paths-before");foreach(int size in new[]{1,3,5,7,9}){var nav=new LabNavigation(live.World,env.State.Fixture.P(54,7));Check(nav.TraceToRoot(env.State.Fixture.P(54,-17),size,new List<Point2>()),"Unchanged protected footprint clearance "+size);}foreach(var cell in new[]{new DualTile(20,-16),new DualTile(21,-16),new DualTile(22,-16),new DualTile(74,-29),new DualTile(75,-29),new DualTile(76,-29)})DirectDig("root-local-emergence",cell.X,cell.Y);yield return Settle();yield return Capture("11-root-paths-emergence");
   var route=new List<Point2>();Check(new LabNavigation(live.World,env.State.Fixture.P(54,7)).TraceToRoot(env.State.Fixture.P(54,-17),9,route),"Large actor route under overhead structure");env.Lab.encounterCount=1;env.Lab.Actors[0].Reset(0,"Large root clearance",route,9,true,LabAttack.ShortMelee);env.Lab.tuning.speed=3;env.Lab.paused=false;for(int i=0;i<480;i++){env.AdvanceEncounters(1.0/60);env.Process(1.0/60);yield return null;if(i==180||i==420)yield return Capture("12-large-under-root-"+i);}env.Lab.paused=true;
   env.Go(0);yield return Settle();yield return Capture("13-remembered-retreat");env.anchor=1;yield return Settle();yield return Capture("14-alternative-foreground");
   for(int i=0;i<5;i++){long t=System.Diagnostics.Stopwatch.GetTimestamp();env.ResetDemo();RecordMetric("reset-"+i,StreamingGeometry.Elapsed(t));yield return Settle();ResourceSample("reset-"+i);Check(env.OwnedMeshes+env.ElevatedOwnedMeshes<=16&&live.Stream.Resident.Count<=384,"Bounded reset "+i);}
   env.debug=true;env.advanced=true;env.showPanel=true;yield return Capture("15-diagnostics-palette");Check(env.EncounterViolations==0,"No concealed actionable attacks during occupied chamber or excavation");Finish();}
  void DirectDig(string label,int x,int y){long t=System.Diagnostics.Stopwatch.GetTimestamp();int n=live.Stream.Dig(new List<DualTile>{new DualTile(env.State.Fixture.X+x,env.State.Fixture.Y+y)});env.Process(0);RecordMetric(label,StreamingGeometry.Elapsed(t),n);RecordMetric(label+"-emergence",env.EmergenceMs,n);}
  IEnumerator ExcavateTo(Point2 target,string label)
  {
   int editsBefore=live.World.EditCount;var source=new Point2(live.Position.x,live.Position.y);var delta=target-source;int steps=(int)Math.Ceiling(LabNavigation.Distance(source,target));var cells=new List<DualTile>();
   for(int i=1;i<=steps;i++)
   {
    var p=source+delta*(i/(double)steps);long t=System.Diagnostics.Stopwatch.GetTimestamp();PreviewDigBrush.Cells(Stage55Preview.V(p),DigBrush.ThreeWide,2.2f,live.World,cells);int n=live.Stream.Dig(cells);env.Process(1.0/60);if(n>0)RecordMetric(label+"-dig",StreamingGeometry.Elapsed(t),n);
    int guard=0;while(Vector2.Distance(live.Position,Stage55Preview.V(p))>.005f&&guard++<1800){var movement=Stage55Preview.V(p)-live.Position;if(live.Ready)live.Step(Vector2.ClampMagnitude(movement/(10f/60),1),movement,false,1f/60);env.Process(1.0/60);if(!env.Lab.paused)env.AdvanceEncounters(1.0/60);if(label=="occupied-chamber"&&env.State.Discovery.Known(env.State.Fixture.X-45,env.State.Fixture.Y-26))Check(env.State.Discovery.Shown(env.State.Fixture.X-45,env.State.Fixture.Y-26),"Threat floor shown on remembered breakthrough");double tick=Time.realtimeSinceStartupAsDouble;yield return null;Record(label+"-excavation",(Time.realtimeSinceStartupAsDouble-tick)*1000);}Check(guard<1800,"Swept playable digging reaches waypoint "+label+" "+i);
   }
   Check(Vector2.Distance(live.Position,Stage55Preview.V(target))<.02f,"Connected dug route reaches "+label);if(label.StartsWith("occupied")||label.StartsWith("large-chamber"))Check(live.World.EditCount>editsBefore,"Actual earth excavated into "+label);env.Process(.15);
  }
  IEnumerator Frames(string phase,int n,bool model=true){double last=Time.realtimeSinceStartupAsDouble;for(int i=0;i<n;i++){if(model)env.Process(1.0/60);if(env.Lab.encounterCount>0&&!env.Lab.paused)env.AdvanceEncounters(1.0/60);yield return null;double now=Time.realtimeSinceStartupAsDouble;Record(phase,(now-last)*1000);last=now;}}
  void Record(string phase,double interval){result.frames.Add(new Frame{phase=phase,interval=interval,host=live.DisplayMs,discovery=env.DiscoveryMs,publication=live.Stream.PresentationMs,structure=env.StructureMs,emergence=env.EmergenceMs,elevated=env.ProjectionMs,encounter=env.EncounterMs,main=main.Valid?main.LastValue*1e-6:-1,allocation=allocation.Valid?allocation.LastValue:-1,build=live.Stream.BuildMs,unload=live.Stream.UnloadMs,upload=live.Gpu.UploadMs,gpu=live.Gpu.ControlMs,resident=live.Stream.Resident.Count,known=env.State.Discovery.Remembered.Count,shown=env.State.Discovery.Visual.Count,uploads=env.StructureUploads,built=live.Stream.TotalBuilt,evicted=live.Stream.TotalEvicted,ready=live.Ready});}
  IEnumerator Settle(){int n=0;do{env.Process(1.0/60,false);yield return null;if(++n>3000){Check(false,"Readiness timeout");yield break;}}while(!live.Ready||live.Stream.PendingPresentation>0||env.State.Discovery.PendingReleases>0);for(int i=0;i<5;i++)yield return null;}
  IEnumerator Capture(string name){yield return null;while(!live.Ready)yield return null;cam.Capture(Path.Combine(output,"captures"),name);cam.captureLabel=false;while(cam.CapturePending)yield return null;File.WriteAllText(Path.Combine(output,"captures",name+".structure.txt"),env.ElevatedDiagnostics());double w=cam.DisplayWidth,h=w/(16.0/9);var p=live.Snapshot;result.shots.Add(new Shot{name=name,above=live.Position.y-p.Unproject(new Point2(0,-h*.5)).Y,below=p.Unproject(new Point2(0,h*.5)).Y-live.Position.y,normalScale=p.ScaleY(p.Focus.Y),anchor=env.anchor,known=env.State.Discovery.Remembered.Count,shown=env.State.Discovery.Visual.Count,resident=live.Stream.Resident.Count,visible=env.VisibleParts,x=live.Position.x,y=live.Position.y});}
  void RecordMetric(string name,double ms,int count=0)=>result.metrics.Add(new Metric{name=name,ms=ms,count=count});
  void ResourceSample(string name){GC.Collect();File.WriteAllText(Path.Combine(output,"progress.txt"),name+" / known "+env.State.Discovery.Remembered.Count+" / laps "+result.laps);result.resources.Add(new Resource{name=name,managed=GC.GetTotalMemory(true),unity=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),meshes=env.GetComponentsInChildren<MeshFilter>().Count(f=>f.name.StartsWith("Stage55 ")),buffers=live.Gpu.BufferCount,materials=live.Gpu.ResourceCount,resident=live.Stream.Resident.Count,pool=live.PooledPresentations});}
  void Check(bool okay,string name){result.checks.Add((okay?"PASS ":"FAIL ")+name);if(!okay){result.error=name;Finish();throw new Exception(name);}}
  void Finish(){if(finished)return;finished=true;File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(result,true));allocation.Dispose();main.Dispose();Application.Quit(result.error==""?0:1);}
 }
